import React, { useState } from 'react';
import '../index.css';

function ExpenseCalculator() {
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState('');
  const [totalExpense, setTotalExpense] = useState(0);

  const handleCalculate = () => {
    setTotalExpense(parseFloat(amount));
  };

  const saveExpenses = async () => {
    try {
      await Promise.all(expenses.map(expense => {
        if (expense.category && expense.amount) {
          return fetch('http://localhost:5000/api/expense/expense', { // Updated endpoint
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              userId: user.id,
              amount: expense.amount,
              category: expense.category,
              description: `Expense for ${expense.category}`
            })
          });
        }
        return Promise.resolve();
      }));
      setMessage('Expenses saved successfully!');
    } catch (err) {
      setMessage('Failed to save expenses');
    }
  };

  return (
    <div className="card">
      <h2>Expense Calculator</h2>
      <input
        type="number"
        placeholder="Amount"
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
      />
      <input
        type="text"
        placeholder="Category"
        value={category}
        onChange={(e) => setCategory(e.target.value)}
      />
      <div className="button-group">
        <button className="btn-primary" onClick={handleCalculate}>Calculate</button>
        <button className="btn-secondary" onClick={handleSave}>Save</button>
      </div>
      <h3>Total Expense: ₹{totalExpense}</h3>
    </div>
  );
}

export default ExpenseCalculator;
